/**
 * Markdown content negotiation on Vercel.
 *
 * Every docs page has a Markdown twin at `<page>.md` (generated by
 * `@ekline/starlight-contextual-menu`). This integration makes a request to
 * the page's own URL with `Accept: text/markdown` return that twin — the
 * convention agents and crawlers use to ask for Markdown without knowing the
 * URL shape. Browsers, which never send `text/markdown`, see no change.
 *
 * Why it is shaped this way — three constraints, all measured:
 *
 *   1. `vercel.json` rewrites cannot do it. `@astrojs/vercel` emits Build
 *      Output API v3, whose generated `.vercel/output/config.json` supersedes
 *      `vercel.json` routing entirely. (They were tried; they were inert.)
 *   2. Astro middleware cannot do it, even in `middlewareMode: 'edge'`: the
 *      adapter's docs say prerendered pages are served from Vercel's filesystem
 *      and never invoke middleware. Every docs page is prerendered.
 *   3. Build Output API `routes` can. A route placed before
 *      `{ "handle": "filesystem" }` is evaluated before static files are
 *      served, and may match on a request header and rewrite.
 *
 * So the integration edits the adapter's own output: after the build, it reads
 * `config.json`, splices in four routes ahead of the filesystem handle, and
 * writes it back. The routes are built by pure functions below so they can be
 * tested without a build; `applyToBuildOutput()` is the only thing that
 * touches the disk.
 *
 * On ordering: this reads two things the adapter produces, and they are not
 * ready at the same time. `@astrojs/vercel` writes `config.json` in its own
 * `astro:build:done`, and Astro runs the adapter's hooks ahead of every site
 * integration's — a probe placed first in the `integrations` array and one
 * placed last both saw the file already there. So `config.json` is safe to
 * read from a plain `astro:build:done`.
 *
 * The static files it copies into `.vercel/output/static/` are not ready at
 * that point: the adapter fills that directory from a second, inner
 * integration it registers for itself while Astro is still setting up config,
 * and an integration registered that way runs *after* every site
 * integration's `astro:build:done` — so `.vercel/output/static/` is still
 * empty when this one's hook fires. What is already complete by then is
 * Astro's own client output, handed to the hook as `dir`; the adapter's later
 * copy is a plain copy of exactly that directory into `.vercel/output/static/`.
 * So this integration reads pages from `dir`, not from
 * `.vercel/output/static/` — the two end up holding identical files, but only
 * one of them exists yet when this hook runs. Both halves measured on a real
 * build rather than assumed; the guard in `applyToBuildOutput` is what catches
 * it if the first half ever changes.
 *
 * A `base` path is handled: the home page's twin moves under it, and
 * `astro:config:setup` passes that prefix through so the home page still
 * negotiates. Every other page needs no special handling, since its twin sits
 * beside its own `index.html` either way.
 *
 * Off Vercel this does nothing at all — checked before any file is read, so a
 * `.vercel/` left behind by an earlier Vercel build cannot make an ordinary
 * build act on it.
 *
 * See wiki/private-docs.md § Markdown content negotiation on Vercel.
 */

import { existsSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join, relative, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

/**
 * The `Accept` header wants Markdown when it lists `text/markdown` as a
 * complete media-type token: `text/markdown`, `text/markdown;q=0.9`,
 * `text/plain, text/markdown, *\/*` all do; `text/markdownx` does not.
 *
 * A regex *source*, used verbatim as a Vercel `has[].value`. Vercel documents
 * that value as a regex but not whether it anchors it to the whole header, so
 * the pattern is written to give the same answer either way — the leading
 * `(^|.*[,\s])` and trailing `([;,\s].*|$)` absorb whatever surrounds the
 * token. Quality values are not evaluated: Build Output routing cannot, and no
 * browser or known agent sends `text/markdown` with a q below `text/html`.
 */
export const ACCEPT_MARKDOWN = String.raw`(^|.*[,\s])text/markdown([;,\s].*|$)`;

const ACCEPT_MARKDOWN_RE = new RegExp(`^(?:${ACCEPT_MARKDOWN})$`);

/** `ACCEPT_MARKDOWN`, applied. For tests and for reading. */
export function acceptsMarkdown(accept) {
	return ACCEPT_MARKDOWN_RE.test(accept ?? '');
}

/** Escapes a slug so it can sit inside a regex alternation as a literal. */
export function escapeRegex(s) {
	return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// Built fresh per route rather than shared: these objects are handed to the
// caller inside the returned config, and one shared `headers` object across
// four routes means a later edit to one route's headers silently rewrites the
// others'.
const varyAccept = () => ({ Vary: 'Accept' });
const wantsMarkdown = () => [{ type: 'header', key: 'accept', value: ACCEPT_MARKDOWN }];

/**
 * The four routes, in the order they must appear. `twins` is
 * `{ root, slugs }` — whether `/` has a twin, and the slugs that do
 * (`reference/errors` for `/reference/errors/` ↔ `/reference/errors.md`).
 *
 * Why four and not two: the rewrite alone would leave the *HTML* response
 * without `Vary: Accept`, and a cached HTML body could then be served to a
 * Markdown request. The first two routes attach the header to every
 * negotiable URL whatever the `Accept` and `continue`, exactly as the adapter's
 * own `_astro` cache-control route does; the last two are the rewrites.
 *
 * Why an alternation and not a route per slug: `config.json` would grow with
 * page count, and Vercel's routing has ceilings. One regex keeps the exact set
 * — a page with no twin never rewrites — at a constant route count.
 *
 * Why `/?$`: the site emits `/reference/errors/`, but Vercel serves the
 * slash-less form too, and both are the same page.
 */
export function negotiationRoutes({ root, slugs }) {
	const routes = [];
	// An empty branch in the alternation matches `/` and would rewrite the home
	// page to a `/.md` that does not exist; one ending in `/` does the same to
	// its parent. `discoverTwins` already refuses to produce either, and this is
	// the second lock: it is this function that turns a slug into a regex, so it
	// is the one place that has to know an empty branch is dangerous.
	const usable = slugs.filter((s) => s && !s.endsWith('/'));
	const slugSrc = usable.length ? `^/(${usable.map(escapeRegex).join('|')})/?$` : null;
	if (slugSrc) routes.push({ src: slugSrc, headers: varyAccept(), continue: true });
	if (root) routes.push({ src: '^/$', headers: varyAccept(), continue: true });
	if (slugSrc) routes.push({ src: slugSrc, has: wantsMarkdown(), dest: '/$1.md', headers: varyAccept() });
	if (root) routes.push({ src: '^/$', has: wantsMarkdown(), dest: '/index.md', headers: varyAccept() });
	return routes;
}

const isNegotiationRoute = (r) => r.dest === '/$1.md' || r.dest === '/index.md';

/**
 * A new config with the negotiation routes spliced in immediately before
 * `{ "handle": "filesystem" }` — the boundary after which Vercel serves static
 * files, so a route must sit before it to be consulted for a prerendered page.
 * Pure: the input is not touched.
 */
export function withMarkdownNegotiation(config, twins) {
	const routes = config.routes ?? [];
	const at = routes.findIndex((r) => r.handle === 'filesystem');
	if (at === -1) {
		throw new Error(
			'[vercel-markdown-negotiation] config.json has no { "handle": "filesystem" } route. ' +
				'The adapter output has changed shape; see wiki/private-docs.md § Markdown content negotiation on Vercel.'
		);
	}
	if (routes.some(isNegotiationRoute)) {
		throw new Error('[vercel-markdown-negotiation] config.json already carries the negotiation routes.');
	}
	return {
		...config,
		routes: [...routes.slice(0, at), ...negotiationRoutes(twins), ...routes.slice(at)],
	};
}

function* walk(dir, depth = 0) {
	for (const entry of readdirSync(dir, { withFileTypes: true })) {
		// `_astro/` is the hashed asset bundle — scripts, styles, images, and on
		// a large site thousands of them. No page twin is ever written there, so
		// descending it is pure cost. Only skipped at the top level, in case a
		// page is ever legitimately called `_astro`.
		if (depth === 0 && entry.isDirectory() && entry.name === '_astro') continue;
		const p = join(dir, entry.name);
		if (entry.isDirectory()) yield* walk(p, depth + 1);
		else yield p;
	}
}

/**
 * Which URLs have a twin, read from the built site. A twin is `<slug>.md`
 * beside `<slug>/index.html`; an `index.md` beside its own `index.html` is the
 * home page's. Anything else — a `.md` dropped into `public/`, a page with no
 * `.md`, the `404.md` beside `404.html` — is not, and never negotiates.
 *
 * `rootSlug` is the path the home page sits at, which is `''` unless a `base`
 * is configured: with `base: '/docs'` the home page is `docs/index.html` and
 * its twin is `docs/index.md`, and `/docs/` is the URL that must negotiate to
 * it. Every other page is found the same way with or without a base, since
 * `<slug>.md` beside `<slug>/index.html` already carries the prefix.
 */
export function discoverTwins(staticDir, rootSlug = '') {
	const rootTwin = rootSlug ? `${rootSlug}/index.md` : 'index.md';
	const rootHtml = rootSlug ? [...rootSlug.split('/'), 'index.html'] : ['index.html'];
	let root = false;
	const slugs = [];
	for (const file of walk(staticDir)) {
		if (!file.endsWith('.md')) continue;
		const rel = relative(staticDir, file).split(sep).join('/');
		if (rel === rootTwin) {
			root = existsSync(join(staticDir, ...rootHtml));
			continue;
		}
		const slug = rel.slice(0, -'.md'.length);
		// A slug has to be a usable URL path segment. An empty one — from a file
		// named bare `.md` — would put an empty branch in the alternation, and
		// an empty branch matches `/`, hijacking the home page and rewriting it
		// to a `/.md` that does not exist. One ending in `/` (from `foo/.md`)
		// does the same to `/foo/`.
		if (!slug || slug.endsWith('/')) continue;
		if (existsSync(join(staticDir, ...slug.split('/'), 'index.html'))) slugs.push(slug);
	}
	slugs.sort();
	return { root, slugs };
}

/** Where `@astrojs/vercel` writes its output, relative to the project root. */
const OUTPUT_DIR = '.vercel/output';

/**
 * Vercel sets `VERCEL=1` on its builders. Anything else — unset, empty, or a
 * value that means "no" — is not a Vercel build. A bare truthiness check would
 * read `VERCEL=0`, the obvious way to say "not Vercel", as "yes".
 */
function isVercelBuild() {
	const flag = process.env.VERCEL;
	return flag !== undefined && flag !== '' && flag !== '0' && flag.toLowerCase() !== 'false';
}

/**
 * Reads the adapter's `config.json`, adds the negotiation routes, writes it
 * back. Returns what it did, or `null` when there is nothing to do.
 *
 * `staticDir` is the built site — the `dir` from `astro:build:done`, not
 * `.vercel/output/static/`, which the adapter has not filled yet when this
 * runs. See the timing note in this file's header.
 *
 * `VERCEL` is checked before anything is read, and that order is load-bearing.
 * A `.vercel/` directory left behind by an earlier Vercel build still holds a
 * `config.json` — one that already carries these routes — so keying off the
 * file's presence instead makes every ordinary build after a Vercel build die
 * on "already carries the negotiation routes". Measured, not imagined.
 *
 * Once we know it IS a Vercel build, a missing `config.json` is the opposite
 * problem: the ordering in this file's header has changed and this ran before
 * the adapter wrote the file. Silence there would ship a deployment quietly
 * lacking the feature — the failure this feature already suffered once — so it
 * throws.
 */
export function applyToBuildOutput({ projectRoot, staticDir, rootSlug = '' }) {
	if (!isVercelBuild()) return null;

	const configPath = join(projectRoot, OUTPUT_DIR, 'config.json');
	if (!existsSync(configPath)) {
		throw new Error(
			`[vercel-markdown-negotiation] VERCEL is set but ${relative(projectRoot, configPath)} was not found ` +
				'when the integration ran. It must run after the adapter writes that file; Astro has run the ' +
				'adapter first in every measured build. See wiki/private-docs.md § Markdown content negotiation on Vercel.'
		);
	}
	const twins = discoverTwins(staticDir, rootSlug);
	let config;
	try {
		config = JSON.parse(readFileSync(configPath, 'utf-8'));
	} catch (cause) {
		throw new Error(
			`[vercel-markdown-negotiation] could not read ${relative(projectRoot, configPath)} as JSON. ` +
				'The adapter writes that file; a failure here means its output is truncated or has changed shape. ' +
				'See wiki/private-docs.md § Markdown content negotiation on Vercel.',
			{ cause }
		);
	}
	writeFileSync(configPath, JSON.stringify(withMarkdownNegotiation(config, twins), null, 2) + '\n');
	return { configPath, ...twins };
}

/**
 * The integration. `astro:config:setup` records the project root;
 * `astro:build:done` does the work — by which time the adapter has already
 * written `config.json` (see the header comment on ordering).
 */
export default function vercelMarkdownNegotiation() {
	let projectRoot;
	let rootSlug = '';
	return {
		name: 'vercel-markdown-negotiation',
		hooks: {
			'astro:config:setup': ({ config }) => {
				projectRoot = fileURLToPath(config.root);
				// `base` defaults to '/'. Normalised to the path the home page sits
				// at within the build output — '' for no base, 'docs' for '/docs'.
				rootSlug = (config.base ?? '').replace(/^\/+|\/+$/g, '');
			},
			'astro:build:done': ({ dir, logger }) => {
				const result = applyToBuildOutput({ projectRoot, staticDir: fileURLToPath(dir), rootSlug });
				if (!result) return;
				const pages = result.slugs.length + (result.root ? 1 : 0);
				const where = relative(projectRoot, result.configPath);
				if (pages === 0) {
					// Nothing to negotiate means the deployment ships without the
					// feature, and a deployment that quietly lacks it is the exact
					// failure this integration exists to prevent — so say so loudly
					// rather than logging a cheerful zero among a thousand build lines.
					logger.warn(
						`no pages answer Accept: text/markdown — no Markdown twins were found in the build ` +
							`output, so ${where} gained no routes. Check that the contextual-menu plugin still ` +
							`has injectMarkdownRoutes enabled.`
					);
					return;
				}
				logger.info(`${pages} pages answer Accept: text/markdown (${where})`);
			},
		},
	};
}
